    lead: "As palavras que você vai encontrar numa mesa de Hold’em, no chat e no próprio PokerTH. As cinco palavras de ação — Fold, Check, Call, Raise e All-In — continuam em inglês nos 71 idiomas da interface, porque é assim em qualquer mesa do mundo.",
