      ["para w ręce", "Dwie karty własne tej samej wysokości."],
      ["pula", "Żetony, o które toczy się bieżące rozdanie."],
      ["szanse puli", "Cena, którą proponuje ci pula: ile musisz sprawdzić wobec tego, ile możesz wygrać."],
      ["przed flopem", "Pierwsza runda licytacji, zanim wyłożona zostanie jakakolwiek karta wspólna."],
      ["tęcza", "Flop w trzech różnych kolorach, przez co natychmiastowy draw do koloru jest niemożliwy."],
      ["przebijam", "Podniesienie bieżącej stawki. W No-Limit o dowolną kwotę aż do całego stacku."],
      ["ponowne przebicie", "Przebicie przebicia."],
      ["river", "Piąta i ostatnia karta wspólna oraz następująca po niej runda licytacji."],
      [null, "Trójka złożona z pary w ręce i jednej pasującej karty na stole — dobrze ukryta, w przeciwieństwie do trips."],
      ["krótki stack", "Stack mały w stosunku do ciemnych, przy którym niewiele zostaje poza pasem albo wejściem za wszystko."],
      ["odkrycie kart", "Odsłonięcie pozostałych układów po ostatniej rundzie licytacji, by rozstrzygnąć, kto wygrywa."],
      ["pula boczna", "Osobna pula tworzona wtedy, gdy gracz jest all-in, a pozostali licytują ponad tę kwotę."],
      [null, "Turniej, który zaczyna się, gdy tylko zapełnią się miejsca, a nie o ustalonej godzinie. Każda gra w PokerTH taka jest."],
      ["wolna gra", "Granie mocnym układem słabo, żeby zatrzymać przeciwników w puli."],
      ["mała ciemna", "Mniejsza z przymusowych stawek, wnoszona bezpośrednio na lewo od rozdającego."],
      ["podzielona pula", "Pula dzielona między układy o równej sile. W Hold’em kolory nigdy nie rozstrzygają remisu."],
      ["stack", "Żetony, które gracz ma przed sobą."],
      [null, "Opcjonalne przebicie w ciemno wnoszone przed rozdaniem. Nieużywane w PokerTH."],
      ["ten sam kolor", "Dwie karty własne w tym samym kolorze."],
      ["tilt", "Granie źle ze złości, zwykle po pechowej przegranej."],
      [null, "Trójka złożona z jednej karty własnej i pary na stole. Dwie z trzech kart widzą wszyscy."],
      ["turn", "Czwarta karta wspólna oraz następująca po niej runda licytacji."],
      ["pod lufą", "Miejsce, które mówi pierwsze przed flopem, bezpośrednio na lewo od dużej ciemnej."],
      ["zakład na wartość", "Zakład postawiony po to, by sprawdził go słabszy układ, a nie po to, by ktoś spasował."],
      ["koło", "Strit A-2-3-4-5, w którym as gra nisko. Najsłabszy strit, jaki istnieje."]
