    desc: "Что означают покерные термины, от all-in до wheel: блайнды, кикер, ауты, шансы банка, сет и трипс, побочные банки и вскрытие — объяснено простым языком.",
    ldHeadline: "Покерный словарь — термины техасского холдема",
