    desc: "Co znamenají pokerové pojmy, od all-in po wheel: blindy, kicker, outy, pot odds, set a trips, vedlejší banky a showdown, vysvětlené srozumitelně.",
    ldHeadline: "Pokerový slovník — pojmy Texas Hold’em vysvětlené",
