      ["چپس کا ڈھیر", "وہ چپس جو کھلاڑی کے سامنے پڑے ہوں۔"],
      ["اسٹریڈل", "تقسیم سے پہلے اختیاری طور پر لگائی گئی اندھی بڑھوتری۔ PokerTH میں استعمال نہیں ہوتی۔"],
      ["ایک ہی رنگ", "ایک ہی رنگ کے دو بند کارڈ۔"],
      ["ٹلٹ", "جھنجھلاہٹ میں برا کھیلنا، عموماً کسی ناحق شکست کے بعد۔"],
      ["کھلی تین", "ہاتھ کے ایک کارڈ اور میز کے جوڑے سے بنی تین۔ تین میں سے دو سب کو نظر آتے ہیں۔"],
      ["ٹرن", "چوتھا مشترکہ کارڈ، اور اس کے بعد آنے والا شرط کا دور۔"],
      ["سب سے پہلے بولنے والا", "وہ نشست جو فلاپ سے پہلے سب سے پہلے حرکت کرتی ہے، بڑے بلائنڈ کے فوراً بائیں۔"],
      ["قدر کی شرط", "ایسی شرط جو اس لیے لگائی جائے کہ کوئی کمزور ہاتھ اسے کال کرے، نہ کہ کسی کو فولڈ کرانے کے لیے۔"],
      ["پہیہ", "<span class=\"ltr\">A-2-3-4-5</span> کا اسٹریٹ، جس میں اِکّا نیچے چلتا ہے۔ سب سے کمزور اسٹریٹ۔"]
