    footer: function (h, c) { return "Još vam nije jasno kako teče jedna ruka? <a href=\"{rules}\">Pravila</a> je prate od uloga do otvaranja karata, a <a href=\"{hands}\">jačina kombinacija</a> navodi što pobjeđuje što.".replace('{rules}', h('rules', c)).replace('{hands}', h('hands', c)); }
