  ca: {
    title: "Glossari de pòquer — termes del Texas Hold’em — PokerTH",
    desc: "Què volen dir els termes del pòquer, d’all-in a wheel: cegues, kicker, outs, probabilitats del pot, set i trips, pots secundaris i obertura de cartes, en llenguatge planer.",
    ldHeadline: "Glossari de pòquer — els termes del Texas Hold’em",
    ldDesc: "Un glossari dels termes del pòquer Texas Hold’em, d’all-in a wheel.",
    h1: "Glossari de pòquer — termes del Texas Hold’em",
    lead: "Les paraules que trobaràs en una taula de Hold’em, al xat i dins el mateix PokerTH. Les cinc paraules d’acció — Fold, Check, Call, Raise i All-In — es mantenen en anglès en els 71 idiomes de la interfície, perquè així és a qualsevol taula del món.",
    terms: [
      ["tot a dins", "Apostar totes les fitxes. Només pots guanyar la part del pot que hagis pagat; la resta va a un pot secundari."],
      ["ante", "Una aposta obligatòria petita que cada jugador paga abans del repartiment, a més de les cegues. S’usa als nivells alts d’alguns tornejos."],
      ["porta del darrere", "Un projecte que necessita tant el turn com el river per completar-se, per exemple dos cors més per a un color."],
      ["mala sort", "Perdre una mà en què eres clarament favorit."],
      ["cega gran", "La més gran de les dues apostes obligatòries, es posa dos seients a l’esquerra del botó. En torneig les piles es compten en cegues grans."],
      ["cegues", "Les dues apostes obligatòries que obren cada mà i donen als jugadors alguna cosa per la qual barallar-se. Al PokerTH pugen per rellotge."],
      ["taula", "Les cinc cartes comunitàries, compartides per tothom."],
      ["bombolla", "El moment d’un torneig just abans que comencin les places pagades o puntuades."],
      ["botó", "El disc que marca el repartidor nominal. Qui seu al botó parla l’últim després del flop: la millor posició de la taula."],
      ["igualar", "Igualar l’aposta actual, res més."],
      ["passar", "Cedir el torn sense apostar. Només és possible si ningú no ha apostat en la ronda en curs."],
      ["passar i pujar", "Passar primer i pujar quan un altre aposta. Una manera de fer créixer el pot amb una mà forta."],
      ["cartes comunitàries", "Les cinc cartes descobertes que tothom pot fer servir, repartides com a flop, turn i river."],
      ["cartes consecutives", "Dues cartes tapades de valors seguits, per exemple 8-9. Si són del mateix pal, comparteixen també el pal."],
      ["projecte", "Una mà incompleta a què falten una o més cartes per ser forta: quatre per a color, quatre per a escala."],
      ["projecte perdut", "Tenir un projecte que no pot guanyar ni quan es completa."],
      ["participació", "La teva part del pot atesos els cartes que encara han de sortir: a la pràctica, amb quina freqüència guanyes des d’aquí."],
      ["flop", "Les tres primeres cartes comunitàries, repartides de cop."],
      ["retirar-se", "Abandonar la mà, i amb ella totes les fitxes ja apostades."],
      ["torneig gratuït", "Un torneig que no costa res per entrar-hi. Al PokerTH ho és cada taula, ja que enlloc no hi ha diners."],
      ["un contra un", "Una mà, o una fase de torneig, on només queden dos jugadors."],
      ["cartes tapades", "Les teves dues cartes privades."],
      ["kicker", "La carta més alta que sobra al costat de la jugada mateixa; desempata entre mans de la mateixa categoria."],
      ["entrada passiva", "Entrar al pot abans del flop igualant només la cega gran en lloc de pujar."],
      ["llençar", "Llençar la mà de cara avall a l’obertura de cartes en comptes de mostrar-la."],
      ["la millor mà possible", "La millor mà que permet la taula. No es pot guanyar, només empatar."],
      ["pals diferents", "Dues cartes tapades de pals diferents."],
      ["cartes útils", "Les cartes que queden a la baralla i et donarien la mà guanyadora. Amb quatre cartes cap a color en queden nou."],
      ["parella alta", "Una parella servida més alta que qualsevol carta de la taula."],
      ["parella servida", "Dues cartes tapades del mateix valor."],
      ["pot", "Les fitxes en joc a la mà actual."],
      ["probabilitats del pot", "El preu que t’ofereix el pot: què has d’igualar davant del que pots guanyar."],
      ["abans del flop", "La primera ronda d’apostes, abans que es reparteixi cap carta comunitària."],
      ["arc de Sant Martí", "Un flop de tres pals diferents, que fa impossible un projecte de color immediat."],
      ["pujar", "Augmentar l’aposta actual. En No-Limit, amb qualsevol import fins a tota la teva pila."],
      ["repujada", "Pujar una pujada."],
      ["river", "La cinquena i última carta comunitària, i la ronda d’apostes que la segueix."],
      ["trio amagat", "Un trio fet d’una parella servida més una carta igual a la taula: ben amagat, a diferència dels trips."],
      ["pila curta", "Una pila petita respecte a les cegues, que deixa poc marge més enllà de retirar-se o anar tot a dins."],
      ["obertura de cartes", "Mostrar les mans que queden després de l’última ronda per decidir qui guanya."],
      ["pot secundari", "Un pot a part que es crea quan un jugador ho ha apostat tot i els altres segueixen apostant per damunt."],
      ["torneig immediat", "Un torneig que comença tan bon punt s’omplen els seients, no a una hora fixa. Cada partida del PokerTH ho és."],
      ["joc lent", "Jugar fluix una mà forta per mantenir els rivals al pot."],
      ["cega petita", "La més petita de les apostes obligatòries, es posa just a l’esquerra del botó."],
      ["pot repartit", "Un pot repartit entre mans d’igual força. Al Hold’em els pals no desempaten mai."],
      ["pila", "Les fitxes que un jugador té al davant."],
      ["straddle", "Una pujada a cegues opcional feta abans del repartiment. No s’utilitza al PokerTH."],
      ["mateix pal", "Dues cartes tapades del mateix pal."],
      ["descontrol", "Jugar malament per frustració, normalment després d’una mala sort."],
      ["trips", "Un trio fet d’una carta tapada i una parella a la taula. Dues de les tres les veu tothom."],
      ["turn", "La quarta carta comunitària, i la ronda d’apostes que la segueix."],
      ["primer a parlar", "El seient que actua primer abans del flop, just a l’esquerra de la cega gran."],
      ["aposta de valor", "Una aposta feta perquè la iguali una mà pitjor, no perquè ningú es retiri."],
      ["la roda", "L’escala A-2-3-4-5, on l’as juga baix. L’escala més fluixa que hi ha."]
    ],
    footer: function (h, c) { return "Encara no tens clar com transcorre una mà? Les <a href=\"{rules}\">regles</a> la segueixen de les cegues fins a l’obertura de cartes, i les <a href=\"{hands}\">jugades de pòquer</a> enumeren què guanya a què.".replace('{rules}', h('rules', c)).replace('{hands}', h('hands', c)); }
  },

