    ldDesc: "all-in မှ wheel အထိ Texas Hold’em ပိုကာ အသုံးအနှုန်းများ၏ ဝေါဟာရ။",
    h1: "ပိုကာ ဝေါဟာရ — Texas Hold’em အသုံးအနှုန်းများ ရှင်းလင်းချက်",
    lead: "Hold’em စားပွဲတွင်၊ ချတ်တွင်နှင့် PokerTH ကိုယ်တိုင်တွင် သင်တွေ့ရမည့် စကားလုံးများ။ လှုပ်ရှားမှုစကားလုံး ငါးလုံး — Fold, Check, Call, Raise နှင့် All-In — သည် မျက်နှာပြင်၏ ဘာသာစကား ၇၁ မျိုးလုံးတွင် အင်္ဂလိပ်လို ရှိနေသည်၊ အကြောင်းမှာ ကမ္ဘာပေါ်ရှိ စားပွဲတိုင်းတွင် ထိုသို့ဖြစ်သောကြောင့်ပင်။",
