    footer: function (h, c) { return "Ende nuk e ke të qartë si zhvillohet një dorë? <a href=\"{rules}\">Rregullat</a> e ndjekin nga blindet deri te showdown, dhe <a href=\"{hands}\">fuqia e kombinimeve</a> liston çfarë mund çfarë.".replace('{rules}', h('rules', c)).replace('{hands}', h('hands', c)); }
