    footer: function (h, c) { return "હેન્ડ કેવી રીતે ચાલે છે તે હજી સ્પષ્ટ નથી? <a href=\"{rules}\">નિયમો</a> તેને બ્લાઇન્ડ્સથી શોડાઉન સુધી સમજાવે છે, અને <a href=\"{hands}\">હેન્ડ રેન્કિંગ</a> શું શાને હરાવે છે તે જણાવે છે.".replace('{rules}', h('rules', c)).replace('{hands}', h('hands', c)); }
